SOURCE='https://ai-trainer-exam-courseware.app.workbuddy.host/?sharecode=U7DGZ5NTK5'
def build():
 material='<p>大型场馆在演唱会、赛事散场时，入口、通道与停车接驳区出现短时集中客流。现有系统只能展示当前人数，缺少风险预测、方案、人员调度和反馈闭环。</p><p>接入闸机、票务核验、区域客流传感器及工作人员移动终端数据，结合区域容量和近期变化，预测未来15分钟风险。达到阈值后生成入口分流、路线引导、人员调度建议，经值班负责人确认后发布，记录执行结果。</p><p>以下参考方案沿用老师课件的功能卡、配置、风险分级和四状态结构。除题设的15分钟与人工确认要求外，阈值、时限、验收值均为设计示例，需经场馆验证和审批；不是题设强制标准。</p>'
 prompts=[
 '分别设计“客流态势监测”“疏导方案生成”“处置反馈闭环”三张功能卡，每项填写功能编号、名称、使用角色及触发条件、功能行为、输出结果和一条可量化验收标准。',
 '绘制6～8个主要节点的系统协同流程图，体现系统处理、业务判断及人员协作闭环；提供JSON配置（forecast_window_minutes、risk_threshold、queue_wait_threshold_minutes、manual_confirm_required）；设计输入输出接口的方向、来源或去向及关键字段；给出3项运营统计或审计内容。',
 '设计不少于3个风险等级，每级说明判断依据、系统响应和业务处置；给出任务从生成到结束的4个主要状态及进入条件；验证日常客流、高峰风险、数据异常三个场景的业务条件、系统与人员协同过程和最终记录。']
 config=dict(forecast_window_minutes=15,risk_threshold=.85,queue_wait_threshold_minutes=10,manual_confirm_required=True,data_refresh_seconds=10,escalation_minutes=10)
 answers=[
 '''<h4>F-01 客流态势监测</h4><p>角色：值班监控员；活动启用时持续监测。融合闸机、票务、区域传感器和移动终端事件，按区域计算当前人数、密度、容量占比及未来15分钟人数趋势，展示风险等级和数据质量标记。输出分区看板和预测预警。验收示例：在约定负载和测量起止点下，区域状态更新延迟不超过10秒；通过历史回放验证。若选用课件的预测MAPE≤15%作为附加目标，须明确零人数处理和样本范围。</p><h4>F-02 疏导方案生成</h4><p>角色：值班负责人；预测风险或等待时间达到已配置阈值时触发。系统生成入口分流、路线引导和人员岗位建议，说明依据、目标区域和生效范围，推送负责人确认；可修改或驳回。输出带版本、待确认状态的方案及批准后的执行任务。验收示例：风险事件产生至可审核方案生成≤60秒；发布事件100%关联有效负责人确认记录，未确认不得发布。</p><h4>F-03 处置反馈闭环</h4><p>角色：现场工作人员与值班负责人；方案发布后启动。现场终端回传执行回执，系统对比执行前后客流，持续观察；无缓解则重新生成升级方案并再次确认，结束后归档。输出执行状态、效果曲线与可追溯档案。验收示例：抽检任务中，生成、确认、发布、执行回执、效果和结束记录完整率100%，可查询导出；未结束任务不能伪造结束记录。</p>''',
 '<h4>配置示例：严格JSON，不写注释</h4><pre>'+html.escape(json.dumps(config,ensure_ascii=False,indent=2))+'</pre><p>risk_threshold是预测人数/区域有效容量的占比阈值，不是模型置信概率。等待超过10分钟作为独立预警触发条件；15分钟预测窗口与确认后发布遵循题设。其余数值是可调整的方案设置。</p>'+'''<h4>输入输出接口</h4><table><tr><th>方向与来源/去向</th><th>关键字段</th></tr><tr><td>闸机、票务→平台</td><td>event_id、通道ID、方向、时间戳、核验结果；按事件ID去重</td></tr><tr><td>区域传感器、基础配置→平台</td><td>区域ID、时间戳、人数、密度、数据质量、区域容量、活动场次</td></tr><tr><td>移动终端→平台</td><td>任务ID、人员ID、岗位、任务版本、执行状态、回传时间</td></tr><tr><td>平台→负责人工作台</td><td>风险等级、预测人数、阈值、方案ID/版本、方案内容、确认状态</td></tr><tr><td>平台→广播、屏显与现场终端</td><td>已批准任务ID/版本、路线、岗位职责、生效时间、回执要求；拒绝未确认及过期版本</td></tr><tr><td>平台→审计档案</td><td>事件、方案、确认人和时间、发布及执行回执、效果与结束理由</td></tr></table><h4>三项统计/审计</h4><ol><li>预警质量：按活动与区域统计次数、经现场核实的命中和误报，说明事件去重、分母、周期和核验来源。</li><li>响应耗时：记录触发、确认、发布、执行及缓解时间，按相同事件口径统计时长与超时任务；未完成任务单列。</li><li>确认合规：已发布任务中有效负责人确认记录的完整率，检查操作权限、版本、先确认后发布及修改留痕。</li></ol>''',
 '''<h4>风险规则：设计示例，边界不重叠，最高等级优先</h4><table><tr><th>等级及依据</th><th>系统响应与业务处置</th></tr><tr><td>常态：占比&lt;70%，且无其他触发</td><td>持续监测、例行巡查，仅记录常态日志。</td></tr><tr><td>蓝色关注：70%≤占比&lt;85%，且无更高等级触发</td><td>关注提示、预备方案不发布，人员关注岗位情况。</td></tr><tr><td>黄色预警：85%≤占比&lt;95%，或等待&gt;10分钟，且无紧急条件</td><td>生成分流、引导、岗位方案，负责人确认后发布；按现场批准方案开放备用通道和引导。</td></tr><tr><td>红色紧急：占比≥95%，或现场达到经审批的安全红线</td><td>强提醒负责人并通知安保，生成紧急方案，确认后发布；人员按场馆应急预案处置，不能因风险高绕过确认。</td></tr></table><p>占比按预测15分钟人数/区域有效容量计算。数据无效时先进入数据异常处理，不能把缺失当作0而判断安全；排队和占比同时触发时取最高风险。</p><h4>四个主要状态</h4><p>待确认：阈值触发后生成方案；执行中：负责人批准并发布后进入；效果观察：收到已执行回执后进入，继续观察客流；已结束：风险回落并稳定，或活动结束且负责人现场确认无需继续疏导，记录理由并归档。驳回/取消进入已结束并标明未执行原因，不能计为疏导成功。观察期未缓解超过示例10分钟，生成升级方案回到待确认；已批准版本修改后须重新确认。发布失败或无回执须告警、人工核实，不得直接记为已执行。</p><h4>运行验证</h4><ol><li>日常：预测低于70%、等待未超限且数据有效。平台监测，人员巡查；断言没有已发布任务，记录常态人数、预测和数据质量。</li><li>高峰：预测占比90%，判黄色。生成方案→负责人确认（2分钟是可设目标）→发布→现场引导并回执→观察回落→稳定后结束。记录触发、方案版本、确认、发布、回执、效果和关闭时间；反向验证未确认不能发布。</li><li>异常：传感器离线或时间戳过期。标记降级并通知运维、值班人员；用闸机、邻区及现场核实辅助判断，估计值明确标注，不当作可靠实测自动解除风险。人员接管，恢复数据经校验后切回正常监测。记录异常起止、估计来源、核实人、运维处理和恢复验证。</li></ol>''']
 c=dict(id='c',kind='case',category='综合评审 · C',title='C · 大型场馆智能客流预测与疏导系统',materialHTML=material,tasks=[dict(id='ct'+str(i+1),title=['产品功能定义','产品方案设计','产品规则配置与运行验证'][i],promptHTML='<p>'+prompts[i]+'</p>',answerHTML=answers[i]) for i in range(3)],steps=[],sourceURL=SOURCE)
 def add(task,title,code,items,hint):
  slots=[dict(answer=a,choices=[a,*w],why=why,matchRule=dict(groups=groups)) for a,w,why,groups in items];solution=code
  for s in slots:solution=solution.replace('{{}}',s['answer'],1)
  c['steps'].append(dict(id='c-'+str(len(c['steps'])+1),taskIndex=task,title=title,goal=hint,code=code,solution=solution,slots=slots,hint=hint,context=''))
 add(0,'功能卡F-01：监测与预测','角色：值班监控员；持续接入多源数据。\n预测未来 {{}} 分钟风险，输出分区看板与质量标记。\n可量化验收示例：{{}}。', [('15',['5','30'],'15分钟是样卷明确的预测窗口。',[]),('区域状态刷新延迟不超过10秒',['只写界面漂亮','只写系统好用'],'须明确测量起止、负载与通过标准，10秒为方案示例。',[['刷新','更新'],['延迟','10秒','十秒']])], '功能卡要覆盖角色、触发、行为、输出与可测验收。')
 add(0,'功能卡F-02：方案与人工确认','触发：预测风险达到已配置阈值。\n方案包括 {{}}。\n发布前必须 {{}}。', [('入口分流、路线引导和人员调度',['只改看板颜色','仅显示历史人数'],'三类建议共同支持客流疏导。',[['分流'],['路线','引导'],['人员','岗位']]),('值班负责人确认',['系统自动绕过确认','由任意访客批准'],'题设要求确认后发布；修改版本后重新确认。',[['负责人'],['确认','批准']])], '方案生成不等于发布，保留审核和版本证据。')
 add(0,'功能卡F-03：反馈闭环','现场终端回传执行状态，观察客流变化。\n未缓解时 {{}}。\n验收示例：{{}}。', [('升级方案并重新确认',['直接沿用旧批准发布新版','删除失败记录'],'效果未改善不能直接假定完成，升级仍需人工确认。',[['升级','调整'],['确认','审批']]),('任务全生命周期记录完整率100%',['仅统计登录次数','只看已成功任务'],'包含生成、确认、发布、回执、效果与结束记录，分母范围明确。',[['记录','留痕'],['完整','100%','百分之百']])], '功能设计必须说明可验证的输出与完整档案。')
 add(1,'绘制八节点系统协同流程','多源接入→预测→风险判断→生成方案\n→ {{}} →发布执行→效果判断→ {{}}。', [('值班负责人确认',['跳过确认','执行后再补批准'],'确认是否通过用菱形表示，未通过回到方案调整。',[['负责人'],['确认']]),('记录归档并反馈监测',['只保存成功结果','删除异常信息'],'常态、驳回、执行异常和效果都应留痕。',[['记录','归档'],['反馈','监测']])], '直接在规范流程图节点中填写，主流程8节点，保留否分支。')
 add(1,'填写有效JSON配置','{\n  "forecast_window_minutes": {{}},\n  "risk_threshold": 0.85,\n  "queue_wait_threshold_minutes": 10,\n  "manual_confirm_required": {{}}\n}', [('15',['5','30'],'预测窗口固定15分钟。',[]),('true',['false','True'],'JSON布尔值为小写true，表示发布前需人工确认。',[['true']])], 'JSON不写注释；0.85和10为老师示例，含义和边界需定义。')
 add(1,'设计输入输出接口','输入必须给出 {{}}。\n输出到广播/屏显/终端时携带 {{}}。', [('方向、来源与关键字段',['只写平台名字','只列界面颜色'],'例如传感器→平台，区域ID、时间戳、人数、质量标志。',[['方向','来源'],['字段']]),('已批准任务ID、版本和生效时间',['未审核草稿','过期指令'],'接口能核对审批状态，拒绝未确认或过期版本。',[['批准','确认'],['任务','id'],['版本','时间']])], '同时写输入来源和输出去向，字段应可支持执行与追溯。')
 add(1,'写出三项运营审计','① {{}}\n② {{}}\n③ 人工确认与操作权限合规审计。', [('预警命中与误报统计',['只计页面访问次数','删掉漏报事件'],'说明周期、核验来源和分母，不能只列指标名。',[['预警','报警'],['命中','误报']]),('触发到确认、发布和见效的耗时',['只统计最快一条','将未完成算零耗时'],'全链路同一事件统计，超时与未完成任务单列。',[['触发'],['确认','发布'],['耗时','时长','时间']])], '预警质量、响应时效、确认合规，各写统计口径。')
 add(2,'配置风险分级与处置','蓝色关注：70%≤占比<85%，预备但不发布。\n黄色：85%≤占比<95%或等待>10分钟，{{}}。\n红色：占比≥95%或安全红线，{{}}。\n冲突时 {{}}。', [('负责人确认后发布疏导方案',['达到阈值即绕过审核','只记录不通知'],'黄色也必须经过负责人确认。',[['确认'],['发布']]),('强提醒负责人并通知安保，确认后应急处置',['无条件自动开关所有入口','忽略现场风险'],'紧急升级不代表绕过题设确认要求，人员按审批预案处置。',[['负责人','安保'],['确认'],['应急','紧急']]),('最高风险优先',['随机选一种等级','始终用最低等级'],'数值是设计示例，区间边界不重叠；无效数据先做异常处理。',[['最高','高风险优先','高等级优先']])], '每级均写判断依据、系统响应、业务动作；示例阈值不是题设硬指标。')
 add(2,'设置四个主要任务状态','待确认→ {{}} → {{}} →已结束。\n效果未缓解需升级时，回到 {{}}。', [('执行中',['直接归档','无需确认'],'负责人批准并发布后进入执行中。',[['执行中']]),('效果观察',['默认成功','自动删除'],'收到现场执行回执后，进入效果观察。',[['效果观察','观察效果']]),('待确认',['绕过确认直接执行','永久使用旧版本批准'],'升级方案仍要负责人确认；驳回结束时记录未执行原因。',[['待确认','重新确认']])], '写清进入条件，未确认不得发布，无回执不得假装已执行。')
 add(2,'验证日常客流场景','数据有效、预测占比<70%、等待未超限。\n系统 {{}}；人员例行巡查。\n最终保留 {{}}。', [('持续监测而不发布疏导任务',['无风险也强制限流','直接暂停所有入口'],'正常场景应断言不产生不必要的已发布任务。',[['监测'],['不发布','不生成']]),('常态监测日志与预测记录',['虚构执行成功任务','清空全部历史'],'日志保留时间、区域、预测和质量标记，支持复核。',[['日志','记录'],['监测','预测']])], '业务条件→系统动作→人员协作→结果证据。')
 add(2,'验证高峰风险场景','预测占比90%，按示例归为 {{}}。\n生成方案→负责人确认→ {{}} →回执与效果观察。\n稳定回落后结束并归档。', [('黄色预警',['蓝色关注','无风险'],'90%落入[85%,95%)，不是红色。',[['黄色','预警']]),('广播、屏显与终端发布执行',['未确认直接执行','只记录不落实'],'回执应关联任务与方案版本，保存确认人和时间。',[['发布'],['执行']])], '反向验证未确认不能发布；耗时目标如2分钟只是可选方案值。')
 add(2,'验证数据异常与恢复','传感器离线或时间戳过期→ {{}}。\n估计数据 {{}}；值班人员现场核实。\n恢复后 {{}}，保留异常起止和处置记录。', [('标记降级并通知运维和值班人员',['将缺失人数设零并判安全','直接删除异常区域'],'缺失不代表安全；通知人员接管并核查数据。',[['降级','异常'],['运维','值班','通知']]),('明确标注来源与质量',['冒充可靠实测','直接据此自动解除风险'],'替代估计不当作可靠实测，不自动解除风险。',[['标注','标记'],['来源','质量','估计']]),('校验通过再切回正常监测',['只要有一条数据就当恢复','不记录恢复时间'],'确认时间、范围、质量与现场状态后恢复，保留验证记录。',[['校验','验证','核验'],['恢复','监测','切回']])], '异常→降级与人工核实→恢复验证，不能把未知当低风险。')
